'use client';
import React from 'react';

import EmojiPicker from 'emoji-picker-react';


// In context: a comment thread under an article. Existing reactions show
// as count chips; "+" opens the compact reactions bar, which expands to
// the full picker.
export type ShellProps = {
  /** The picker root: EmojiPicker, or a styled() wrapper of it. */
  Root?: React.ComponentType<React.ComponentProps<typeof EmojiPicker>>;
  className?: string;
};

const chips = [
  ['👍', 12, true],
  ['🎉', 4, false],
  ['💡', 3, false],
] as const;

export function Shell({ Root: RootComponent = EmojiPicker, className }: ShellProps) {
  return (
    <article className="comments-card">
      <h2 className="comments-title">3 comments</h2>
      <div className="comments-item">
        <span className="comments-avatar" aria-hidden>
          RK
        </span>
        <div className="comments-body">
          <p className="comments-meta">
            <strong>Rosa Kim</strong> · 2h ago
          </p>
          <p>
            The section on progressive enhancement finally made it click for
            me. Bookmarking this one.
          </p>
          <div className="comments-reactions">
            {chips.map(([emoji, count, mine]) => (
              <button
                key={emoji}
                type="button"
                className="comments-chip"
                aria-pressed={mine}
                aria-label={`${emoji} ${count} reactions`}
              >
                <span aria-hidden>{emoji}</span> {count}
              </button>
            ))}
            <button type="button" className="comments-chip comments-add" aria-label="Add reaction" aria-expanded="true">
              ＋
            </button>
          </div>
          <div className="comments-popover">
            <RootComponent
              className={className}
              reactionsDefaultOpen
              reactions={['1f44d', '2764-fe0f', '1f602', '1f389', '1f914', '1f440', '1f525']}
              width={360}
              height={400}
            />
          </div>
        </div>
      </div>
    </article>
  );
}

/* The host app around the picker (shared by every stack variant). */
.comments-card {
  width: 520px;
  min-height: 330px;
  padding: 22px 24px;
  border: 1px solid #e5e7eb;
  border-radius: 16px;
  background: #ffffff;
  color: #1f2937;
  font-family: Georgia, 'Times New Roman', serif;
}
.comments-title {
  margin: 0 0 16px;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 15px;
}
.comments-item {
  display: flex;
  gap: 12px;
}
.comments-avatar {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: none;
  border-radius: 50%;
  background: #0f766e;
  color: #ffffff;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
}
.comments-body p {
  margin: 0 0 8px;
  font-size: 16px;
  line-height: 1.55;
}
.comments-body .comments-meta {
  color: #4b5563;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 13px;
}
.comments-meta strong {
  color: #111827;
}
.comments-reactions {
  display: flex;
  gap: 6px;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.comments-chip {
  height: 30px;
  padding: 0 10px;
  border: 1px solid #e5e7eb;
  border-radius: 999px;
  background: #f9fafb;
  color: #374151;
  font: inherit;
  font-size: 13px;
}
.comments-chip[aria-pressed='true'] {
  border-color: #99f6e4;
  background: #f0fdfa;
  color: #115e59;
}
.comments-add {
  width: 34px;
  padding: 0;
  border-style: dashed;
}
.comments-popover {
  margin-top: 8px;
}

/* Article comments — a rounded-rectangle reactions bar matching the
   comment chips; expands to a light full picker. */
.comments-picker {
  --epr-bg-color: #ffffff;
  --epr-reactions-bg-color: #ffffff;
  --epr-text-color: #4b5563;
  --epr-highlight-color: #0f766e;
  --epr-hover-bg-color: #f0fdfa;
  --epr-hover-bg-color-reduced-opacity: #f0fdfa;
  --epr-focus-bg-color: #ccfbf1;
  --epr-picker-border-color: #e5e7eb;
  --epr-search-border-color-active: #14b8a6;
  --epr-category-icon-active-color: #0f766e;
  --epr-category-label-text-color: #4b5563;
  --epr-picker-border-radius: 14px;
  box-shadow: 0 10px 30px rgb(17 24 39 / 12%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.comments-picker [data-epr-part='reaction'] {
  border-radius: 10px;
}
.comments-picker [data-epr-part='category-label'] {
  font-size: 13px;
  text-transform: none;
}

/* Generated by scripts/generateRecipes.mts from picker.css — do not edit. */
.picker {
  --epr-bg-color: #ffffff;
  --epr-reactions-bg-color: #ffffff;
  --epr-text-color: #4b5563;
  --epr-highlight-color: #0f766e;
  --epr-hover-bg-color: #f0fdfa;
  --epr-hover-bg-color-reduced-opacity: #f0fdfa;
  --epr-focus-bg-color: #ccfbf1;
  --epr-picker-border-color: #e5e7eb;
  --epr-search-border-color-active: #14b8a6;
  --epr-category-icon-active-color: #0f766e;
  --epr-category-label-text-color: #4b5563;
  --epr-picker-border-radius: 14px;
  box-shadow: 0 10px 30px rgb(17 24 39 / 12%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.picker [data-epr-part='reaction'] {
  border-radius: 10px;
}
.picker [data-epr-part='category-label'] {
  font-size: 13px;
  text-transform: none;
}
